public void testDoNotInlineCatchExpression1a() {
  noInline(
      "var a;\n" +
      "try {\n" +
      "  throw Error(\"\");\n" +
      "}catch(err) {" +
      "   a = err + 1;\n" +
      "}\n" +
      "return a.stack\n");
}

public void testDoNotInlineCatchExpression1() {
  noInline(
      "var a;\n" +
      "try {\n" +
      "  throw Error(\"\");\n" +
      "}catch(err) {" +
      "   a = err;\n" +
      "}\n" +
      "return a.stack\n");
}
